css:
/* Reset default styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

/* Center buttons on the screen */
body {
    display: flex;
    justify-content: center;
    align-items: center;
    flex-direction: column;
    min-height: 100vh;
    gap: 30px;
    background: #1c2630;
}

/* Button styling */
.button {
    position: relative;
    padding: 10px 30px;
    font-size: 1em;
    background: transparent;
    border: 2px solid var(--color);
    font-weight: 500;
    border-radius: 40px;
    cursor: pointer;
    color: var(--color);
    letter-spacing: 0.1em;
    text-transform: uppercase;
    transition: 1s;
    overflow: hidden;
}

/* Glowing hover effect */
.button:hover {
    background: var(--color);
    box-shadow: 0 0 25px var(--color), 0 0 100px var(--color),
        0 0 150px var(--color);
}

/* Text animation effect */
.button span {
    position: relative;
    display: inline-block;
    transition: transform 0.5s;
    text-shadow: 0 35px #fff;
    transform: translateY(0px);
}

/* Move text up on hover */
.button span.hover {
    transform: translateY(-35px);
}

